"""Declarative base and shared column mixins.

Models live in app/models (Schema.md Section 2). Importing `app.models` registers
every table on `Base.metadata`, which is what Alembic autogenerate reads.
This module deliberately imports no models, so models can import from it freely.
"""

import datetime as dt
import uuid

from sqlalchemy import DateTime, Uuid, func, text
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column


class Base(DeclarativeBase):
    pass


def uuid_pk() -> Mapped[uuid.UUID]:
    """UUID primary key generated by Postgres (`gen_random_uuid()`, core since PG13)."""
    return mapped_column(
        Uuid(as_uuid=True),
        primary_key=True,
        server_default=text("gen_random_uuid()"),
    )


class TimestampMixin:
    """`created_at` / `updated_at` pair used by most tables in Schema.md."""

    created_at: Mapped[dt.datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        server_default=func.now(),
    )
    updated_at: Mapped[dt.datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        server_default=func.now(),
        onupdate=func.now(),
    )
